CREATE TYPE "ScriptStatus" AS ENUM ('DRAFT', 'REVISION_PENDING', 'APPROVED', 'REJECTED');
CREATE TYPE "ProviderRequestStatus" AS ENUM ('SUCCEEDED', 'FAILED');
CREATE TABLE "scripts" ("id" UUID NOT NULL, "workspace_id" UUID NOT NULL, "channel_id" UUID, "series_id" UUID, "approved_idea_snapshot_id" UUID NOT NULL, "approved_idea_checksum" TEXT NOT NULL, "status" "ScriptStatus" NOT NULL DEFAULT 'DRAFT', "current_revision" INTEGER NOT NULL DEFAULT 1, "approved_at" TIMESTAMPTZ(6), "created_by_user_id" UUID NOT NULL, "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(6) NOT NULL, CONSTRAINT "scripts_pkey" PRIMARY KEY ("id"));
CREATE TABLE "script_revisions" ("id" UUID NOT NULL, "workspace_id" UUID NOT NULL, "script_id" UUID NOT NULL, "revision" INTEGER NOT NULL, "document" JSONB NOT NULL, "prompt_version" TEXT, "model_version" TEXT, "cost" DECIMAL(18,8), "cost_currency" TEXT, "config_snapshot_id" UUID, "created_by_user_id" UUID NOT NULL, "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "script_revisions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "provider_requests" ("id" UUID NOT NULL, "workspace_id" UUID NOT NULL, "channel_id" UUID, "correlation_id" UUID NOT NULL, "provider_id" TEXT NOT NULL, "capability_id" TEXT NOT NULL, "status" "ProviderRequestStatus" NOT NULL, "usage" JSONB, "estimated_cost" DECIMAL(18,8), "actual_cost" DECIMAL(18,8), "currency" TEXT, "latency_ms" INTEGER, "response_metadata" JSONB, "error_code" TEXT, "error_message" TEXT, "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "provider_requests_pkey" PRIMARY KEY ("id"));
CREATE TABLE "provider_budgets" ("id" UUID NOT NULL, "workspace_id" UUID NOT NULL, "channel_id" UUID, "daily_limit" DECIMAL(18,8) NOT NULL, "currency" TEXT NOT NULL, "reserved" DECIMAL(18,8) NOT NULL DEFAULT 0, "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(6) NOT NULL, CONSTRAINT "provider_budgets_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "scripts_workspace_id_id_key" ON "scripts"("workspace_id", "id"); CREATE INDEX "scripts_workspace_id_status_created_at_idx" ON "scripts"("workspace_id", "status", "created_at");
CREATE UNIQUE INDEX "script_revisions_workspace_id_script_id_revision_key" ON "script_revisions"("workspace_id", "script_id", "revision"); CREATE UNIQUE INDEX "script_revisions_workspace_id_id_key" ON "script_revisions"("workspace_id", "id");
CREATE UNIQUE INDEX "provider_requests_workspace_id_id_key" ON "provider_requests"("workspace_id", "id"); CREATE INDEX "provider_requests_workspace_id_created_at_idx" ON "provider_requests"("workspace_id", "created_at");
CREATE UNIQUE INDEX "provider_budgets_workspace_id_channel_id_key" ON "provider_budgets"("workspace_id", "channel_id");
ALTER TABLE "scripts" ADD CONSTRAINT "scripts_workspace_id_fkey" FOREIGN KEY ("workspace_id") REFERENCES "workspaces"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "scripts" ADD CONSTRAINT "scripts_workspace_id_approved_idea_snapshot_id_fkey" FOREIGN KEY ("workspace_id", "approved_idea_snapshot_id") REFERENCES "idea_approval_snapshots"("workspace_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "scripts" ADD CONSTRAINT "scripts_created_by_user_id_fkey" FOREIGN KEY ("created_by_user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "script_revisions" ADD CONSTRAINT "script_revisions_workspace_id_script_id_fkey" FOREIGN KEY ("workspace_id", "script_id") REFERENCES "scripts"("workspace_id", "id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "script_revisions" ADD CONSTRAINT "script_revisions_created_by_user_id_fkey" FOREIGN KEY ("created_by_user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "provider_requests" ADD CONSTRAINT "provider_requests_workspace_id_fkey" FOREIGN KEY ("workspace_id") REFERENCES "workspaces"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "provider_budgets" ADD CONSTRAINT "provider_budgets_workspace_id_fkey" FOREIGN KEY ("workspace_id") REFERENCES "workspaces"("id") ON DELETE CASCADE ON UPDATE CASCADE;
